import sys
sys.dont_write_bytecode=True
import review as v
import collections,itertools,json,pathlib,hashlib
R=v.R;h=v.h;read=v.read;save=v.save

def visible_rows(rs):
 rows=[]
 for r in rs:
  ch=h.field(r)[':answer-field/choices'];parts=[v.parts(c[':answer/value']) for c in ch];idx=next(i for i,c in enumerate(ch) if c[':answer/id']==h.key(h.field(r)))
  arg_counts=collections.Counter(arg for c,arg in parts)
  distinct=sorted(set(c for c,arg in parts));c,arg=parts[idx]
  rows.append({'id':r['question'][':question/id'],'profile':'one argument' if len(arg_counts)==1 else 'mixed arguments','correct_position':idx,'correct_coefficient_rank':distinct.index(c),'distinct_coefficients':len(distinct),'correct_coefficient':str(c),'correct_argument_multiplicity':arg_counts[arg],'correct_value':v.norm(ch[idx][':answer/value']),'signature':tuple(sorted(v.norm(c[':answer/value']) for c in ch)),'parameters':r['generation']['parameters']})
 return rows

def stats(rs):
 rows=visible_rows(rs);groups=collections.defaultdict(list)
 for row in rows:groups[row['signature']].append(row)
 return {'count':len(rows),'profiles':dict(collections.Counter(r['profile'] for r in rows)),'slope_cases':dict(collections.Counter('negative' if r['parameters'][1]<0 else 'positive unit' if r['parameters'][1]==1 else 'positive nonunit' for r in rows)),'shift_cases':dict(collections.Counter('negative' if r['parameters'][2]<0 else 'positive' if r['parameters'][2]>0 else 'zero' for r in rows)),'historical_cue':h.probe(rs),'bank_groups':[{'count':len(group),'distinct_keys':len(set(r['correct_value'] for r in group)),'signature':list(sig),'records':[r['id'] for r in group]} for sig,group in groups.items()],'rows':rows}

stages={}
for name in ['batch','samples','controls','counterfactual-records','natural-boundary-records']:
 stages[name]={'raw':stats(read(R/(name+'.json'))),'delivered':stats(read(R/('delivery-'+name)/'accepted.json')),'delivery':read(R/('delivery-'+name)/'delivery.json')}
save('coverage-and-shortcuts.json',stages)
probes=[]
for name in ['batch','controls','samples','counterfactual-records']:
 for stage,path in [('raw',name+'.json'),('delivered','delivery-'+name+'/accepted.json')]:
  rs=read(R/path);rows=visible_rows(rs)
  for subgroup in sorted(set(r['profile'] for r in rows)):
   sub=[r for r in rows if r['profile']==subgroup]
   for cue,strategy,pred in [('coefficient magnitude','Choose the largest coefficient; break ties by lexical argument, without consulting the prompt.',lambda r:r['correct_coefficient_rank']==r['distinct_coefficients']-1),('first authored option','Choose index zero in the generator bank, without reading mathematics.',lambda r:r['correct_position']==0)]:
    # Largest coefficient ties do not select a unique answer; use lexical tie break explicitly.
    if cue=='coefficient magnitude':
     selected=[]
     for rr in rs:
      row=next(row for row in rows if row['id']==rr['question'][':question/id'])
      if row['profile']!=subgroup:continue
      choices=h.field(rr)[':answer-field/choices']; chosen=max(choices,key=lambda c:v.parts(c[':answer/value']))
      selected.append(chosen[':answer/id']==h.key(h.field(rr)))
     correct=sum(selected)
    else:correct=sum(pred(r) for r in sub)
    probes.append({'cue':cue,'subgroup':name+' '+stage+': '+subgroup,'scope':'other_recognizable_subgroup','strategy':strategy,'correct':int(correct),'total':len(sub),'baseline':0.2,'disposition':'not_predictive','conclusion':'Baseline is uniform choice among five options. Successes are bounded sample measurements, not a universal probability claim. Both bank templates admit all five correct roles; no tested bank-only rule solves this subgroup. Authored order is additionally shuffled by the UI.','sample_refs':[path,'coverage-and-shortcuts.json']})
 # Old composite rule applied to actual delivered records.
 p=h.probe(read(R/('delivery-'+name)/'accepted.json'))
 probes.append({'cue':'Historical sign/argument bank signature','subgroup':name+' delivered','scope':'overall','strategy':'Two-negative bank: largest positive coefficient; three-negative bank: negative proper fraction; mixed bank: unique positive unit shifted logarithm.','correct':p['correct'],'total':p['total'],'baseline':0.2,'disposition':'not_predictive','conclusion':'Uniform five-choice baseline is 0.2. The retained exploit no longer solves this pool; absence of an eligible unique choice counts as failure.','sample_refs':['delivery-'+name+'/accepted.json','coverage-and-shortcuts.json']})

# Confirm UI order specifically from actual screenshots/report; don't pretend author order is UI order.
reports=[read(R/'render/rendering.json'),read(R/'render-remaining/rendering.json')]
render_records=read(R/'render-records.json')[:6]+read(R/'render-remaining.json')[:6]
cases=reports[0]['cases']+reports[1]['cases'];assert len(cases)==12
ui_positions=[]
for r,case in zip(render_records,cases):
 # Text marks the correct selected radio and the preceding unselected choices.
 text=case['text'];before=text.split('Correct choice selected.')[0]
 pos=before.count('Incorrect choice left unselected.')
 ui_positions.append({'id':r['question'][':question/id'],'position':pos,'profile':r['generation']['profile'],'screenshot':str(pathlib.Path(case['screenshot']).relative_to(R))})
save('ui-positions.json',ui_positions)
for sub in ['coefficient-choice','argument-choice']:
 rows=[r for r in ui_positions[1:] if r['profile']==sub] # defect excluded from pedagogical probe
 probes.append({'cue':'First visible radio','subgroup':'Rendered valid '+sub,'scope':'within_template','strategy':'Always choose the top displayed radio option.','correct':sum(r['position']==0 for r in rows),'total':len(rows),'baseline':0.2,'disposition':'not_predictive','conclusion':'Baseline is 1/5. Actual UI ordering varies; this small render subset is chosen for counterfactual inspection, not a random estimate. Top position is not a fixed key in either template.','sample_refs':['ui-positions.json','render-records.json','render-remaining.json']})

sel={'inventory_basis':5669,'code_refs':['engine/rust/question_selection.rs:124-198','engine/rust/learning.rs:149-176','engine/rust/learning.rs:1580','ui/learning.js:690-693'],'generator_rejection':'candidates chooses eligible small integer banks directly; batch rejects entire groups if any mathematical fingerprint occurred before and assigns all five targets in seeded shuffled order. Partial final groups are truncated. The 5-item target batch and two fresh 5-item batches have no within-bank repeated integrands. Zero-intercept formatting is not rejected.','captured_inventory':read(R/'inventory-review.json'),'eligibility':'All five original easy questions with keys remain eligible; incomplete q-49511 lacks its radio key and is excluded by validate_response_question. Retired questions are excluded separately. No stored generated records exist.','publication_preparation_exists':(R.parent/'publication/preparation.json').exists(),'filtering':{name:{k:stages[name]['delivery'][k] for k in ['input_count','duplicate_count','accepted_count']} for name in stages},'learner_selection':'Candidates are ID-deduplicated, filtered for usable/fresh state upstream, and drawn uniformly within the selected difficulty band. All current candidates are easy, so a positive easy weight does not favor a bank role within that band. The unconfigured policy fallback chooses the first entity ID; future entity IDs and learner history are not supplied. A zero easy weight yields no rated easy candidate. A learner history can remove roles; this does not create a content-intrinsic universal shortcut in the full new pool.','history_subsets':[],'limits':['No live learner history, configured weights or future entity IDs supplied; cannot predict a particular learner sequence.','Capture basis 5669 only; later inventory can alter deduplication.','Malformed zero-intercept candidates are structurally eligible; math is not checked by delivery or radio grading.']}
rows=visible_rows(read(R/'delivery-batch/accepted.json'))
for length in range(1,6):
 for inds in itertools.combinations(range(5),length):
  sub=[rows[i] for i in inds];sel['history_subsets'].append({'remaining_indices':inds,'distinct_correct_values':len(set(r['correct_value'] for r in sub)),'best_constant_bank_choice_success':1/length})
save('selection-analysis.json',sel)

variation={'learner_operation':'Recognize u=ax+b, determine the slope a, scale the numerator n by 1/a, and select (n/a)ln|ax+b|+C while distinguishing coefficient and argument errors.','fixed_features':[{'feature':'One affine denominator, one constant numerator, one indefinite integral.','justification':'Canonical e-449 and the general-formula tutorial teach one reciprocal substitution; combinations belong to adjacent KPs.'},{'feature':'Five math radio choices with exactly one answer.','justification':'All six captured practice banks use this response contract.'},{'feature':'New bank options share the slope and have positive numerator candidates.','justification':'All source numerators are positive. Keeping easy integer numerators and a common slope does not fix the correct candidate: all five bank candidates become targets. Determining n/a remains necessary. Signed slope still varies.'}],'answer_roles':[{'role':'Correct coefficient sign, magnitude and rank','eligible_variation':'Both slope signs; unit/nonunit slopes; each eligible coefficient rank may be correct.','observed':'All five keys occur for identical banks in the target batch and both controlled profiles; positive and negative slopes occur in the regression sample.'},{'role':'Correct logarithm argument','eligible_variation':'Preserve the affine argument matching the integrand; allow either argument group in a mixed bank to supply the answer.','observed':'Target batch has 2 choices with 8x+4 and 3 with 8x+6; each becomes correct. Controlled mixed bank likewise varies its qualifying argument.'},{'role':'Correct position','eligible_variation':'Radio position is incidental and should not predict the answer.','observed':'Generator and actual UI shuffle positions; both controlled templates have distinct displayed correct positions.'}],'coverage':[{'case':name,'sample_refs':[name+'.json','delivery-'+name+'/accepted.json','coverage-and-shortcuts.json'],'result':f"{stages[name]['raw']['count']} raw, {stages[name]['delivered']['count']} delivered. "+('All five choices become keys of one common bank.' if name=='batch' else 'Decision coverage and per-profile bank/signature measurements retained.')} for name in ['batch','samples','controls','counterfactual-records']]+[{'case':'Zero intercept with positive unit slope','sample_refs':['minimal-failure.json','natural-boundary-records.json','zero-intercept-regression.json'],'result':'Invalid x0 notation in this supported decision case; math/rendering fail independently of varied answer-role assignments.'}],'counterfactuals':[{'kind':'relevant','change':'Hold each five-choice bank fixed; vary the numerator and, in the mixed template, the intercept that supplies the integrand.','expected':'The keyed antiderivative must track the selected n/a and argument; prompt and worked substitution must change with the target.','observed':'Five distinct prompts, solutions and correct values per bank; all choices independently differentiated and exercised in the native grader. Rendered coefficient and argument changes match.','status':'passed','justification':'Canonical substitution and source shifted-argument distractors make both coefficient and argument relevant.','sample_refs':['counterfactual-records.json','counterfactuals.json','math.json','grader-report.json','render-records.json','render-remaining.json']},{'kind':'irrelevant','change':'Hold parameters and full bank fixed; change only the seeded option order.','expected':'Preserve prompt, solution and correct mathematical value; grading must accept that value at its new position.','observed':'Both profiles preserve all three dependencies, change choice order, and pass native correct/wrong-choice tests. Both rendered before/after pairs inspected.','status':'passed','justification':'Radio option order is absent from the source integration rule.','sample_refs':['counterfactual-records.json','counterfactuals.json','grader-report.json','render-records.json','render-remaining.json']}],'shortcut_probes':probes,'delivery':{'stages_examined':['generator construction and rejection','requested difficulty','shared publication normalization','inventory and batch deduplication','practice eligibility and retired filtering','within-band learner selection and history subsets','actual UI choice order'],'sample_refs':['coverage-and-shortcuts.json','delivery-batch/accepted.json','delivery-batch/delivery.json','delivery-natural-boundary-records/accepted.json','selection-analysis.json','inventory-review.json'],'result':'The five runner records survive and have five different keys in a shared bank; old shortcut no longer solves them. Fresh controls retain coverage. Dedup removes two irrelevant reorder duplicates from controlled pairs. All five malformed seed-575 records also survive, so separate math failure remains deliverable.'},'limitations':['Finite probes do not prove absence of every shortcut.','The current batch supplies only one mixed-argument bank; it supports practice on five different numerator/argument decisions, not independent coverage of every slope sign.','Math and notation validity fail at a=1,b=0; pedagogical key-variation success does not waive this defect.','Selection conclusions are conditional on captured inventory and supplied code; no live learner policy/history is available.']}
save('pedagogical-variation.json',variation)

save('render-inspection.json',{'automatic_reports':['render/rendering.json','render-remaining/rendering.json'],'automatic_pass':all(r['passed'] for r in reports),'screenshots_inspected':['render/question-001.png','render/question-002.png','render/question-003.png','render/question-004.png','render/question-005.png','render/question-006.png'],'remaining_screenshots_pending':True,'findings':'First screenshot visibly displays denominator x0, logarithms |x0|, and the false derivative du/dx=1 for u=x0. This is generator math/notation corruption, despite no MathJax syntax errors. Other inspected counterfactual screens have readable controls and correct changing prompts/solutions.'})
save('retained-findings-review.json',{'finding_ids':['9c7856089e1ac50b09d1','4bb13dd660b79e861b1a'],'preflight_claim':read(R.parent/'repair-preflight.json'),'independent_before':'retained-before.json','independent_current':'retained-current.json','author_rerun':'author-check/validation-summary.json','result':'Both retained failures reproduced on previous package and tested current package. Both are resolved for exercised cases. Author preflight passes but omits a=1,b=0; new independent boundary test fails.','commands':['context-python regression.py --package ../review-0-policy-2-6273cf8765511f83/relocated --candidate-records ../review-0-policy-2-6273cf8765511f83/delivery-batch/accepted.json --output retained-before.json','context-python regression.py --candidate-records batch.json --output retained-current.json','context-python author-regression.py','context-python zero-intercept-regression.py']})
